/**
 * Events emitted by the mobile core to the Swift layer.
 */

public enum CoreEvent: Equatable, Hashable {
    
    /**
     * Daemon connection status changed.
     */
    case daemonStatusChanged(daemon: String, status: DaemonStatus
    )
    /**
     * Full or updated session list for a daemon.
     */
    case sessionList(daemon: String, sessions: [SessionSummary]
    )
    /**
     * Project list for a daemon (response to list_projects).
     */
    case projectList(daemon: String, projects: [ProjectInfo]
    )
    /**
     * Directory listing (response to list_dir).
     */
    case dirListing(daemon: String, sessionId: String, path: String, entries: [DirEntry]
    )
    /**
     * A session was reloaded after reconnect. Swift should pull `snapshot()`.
     */
    case sessionReloaded(daemon: String, sessionId: String
    )
    /**
     * Streaming text delta for a part. Coalesced in Rust before FFI.
     */
    case textDelta(daemon: String, sessionId: String, partId: String, delta: String
    )
    /**
     * A part's state was updated (tool state, reasoning, errors).
     */
    case partUpdated(daemon: String, sessionId: String, partId: String, partKind: String, state: String?
    )
    /**
     * A turn ended (MessageEnd received).
     */
    case turnEnded(daemon: String, sessionId: String, inputTokens: UInt64, outputTokens: UInt64, cost: Double, failed: Bool
    )
    /**
     * A permission request from the agent.
     */
    case permissionRequested(daemon: String, sessionId: String, requestId: UInt64, toolName: String, input: String
    )
    /**
     * An ask-user request from the agent.
     */
    case askUserRequested(daemon: String, sessionId: String, requestId: UInt64, callId: String, questions: [String]
    )
    /**
     * A request was resolved (by this device or another). Dismiss the sheet.
     */
    case requestResolved(daemon: String, requestId: UInt64
    )
    /**
     * Cross-session alert from the daemon.
     */
    case alert(daemon: String, sessionId: String, kind: String, title: String, detail: String?
    )
    /**
     * Attention count changed for a session.
     */
    case attentionChanged(daemon: String, sessionId: String, pendingPermissions: UInt32, pendingQuestions: UInt32
    )
    /**
     * Todo list updated for a session.
     */
    case todosUpdated(daemon: String, sessionId: String, todos: [TodoItem]
    )
    /**
     * Permission mode changed (via cross-device or local action).
     */
    case permissionModeChanged(daemon: String, mode: String
    )
    /**
     * Model was switched (via cross-device or local action).
     */
    case modelSwitched(daemon: String, provider: String, model: String
    )
    /**
     * Thinking variant changed.
     */
    case thinkingVariantChanged(daemon: String, variant: String?
    )
    /**
     * Available models from the daemon.
     */
    case modelList(daemon: String, models: [ModelSummary]
    )
    /**
     * Slash command result text.
     */
    case slashResult(daemon: String, sessionId: String, text: String
    )
    /**
     * Daemon version from Pong.
     */
    case daemonVersion(daemon: String, version: String
    )





}

