/**
 * Connection status for a daemon.
 */

public enum DaemonStatus: Equatable, Hashable {
    
    case disconnected
    case connecting
    case connected
    /**
     * Backing off before reconnect attempt N.
     *
     * `error` carries the human-readable reason for the most recent
     * failure so the UI can surface it instead of a generic "retrying"
     * string. Empty when no specific reason is available.
     */
    case backoff(attempt: UInt32, error: String
    )
    /**
     * Pairing was lost (NodeId changed or unauthorized).
     */
    case pairedLost





}

#if compiler(>=6)
extension DaemonStatus: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeDaemonStatus: FfiConverterRustBuffer {
    typealias SwiftType = DaemonStatus

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> DaemonStatus {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .disconnected
        
        case 2: return .connecting
        
        case 3: return .connected
        
        case 4: return .backoff(attempt: try FfiConverterUInt32.read(from: &buf), error: try FfiConverterString.read(from: &buf)
        )
        
        case 5: return .pairedLost
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: DaemonStatus, into buf: inout [UInt8]) {
        switch value {
        
        
        case .disconnected:
            writeInt(&buf, Int32(1))
        
        
        case .connecting:
            writeInt(&buf, Int32(2))
        
        
        case .connected:
            writeInt(&buf, Int32(3))
        
        
        case let .backoff(attempt,error):
            writeInt(&buf, Int32(4))
            FfiConverterUInt32.write(attempt, into: &buf)
            FfiConverterString.write(error, into: &buf)
            
        
        case .pairedLost:
            writeInt(&buf, Int32(5))
        
        }
    }
}


